func (os SettlementLineSlice) Member(mods ...bob.Mod[*dialect.SelectQuery]) MembersQuery {
	pkMemberID := make(pgtypes.Array[uuid.UUID], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenMemberID := make(map[uuid.UUID]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenMemberID[o.MemberID]; ok {
			continue
		}
		seenMemberID[o.MemberID] = struct{}{}
		pkMemberID = append(pkMemberID, o.MemberID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkMemberID), "uuid[]"))

	return Members.Query(append(mods,
		sm.Where(Members.Columns.ID.EQ(PKArgExpr)),
	)...)
}

