// settlementLineWhereR holds the relationship-based filters of
// settlementLineWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type settlementLineWhereR[Q psql.Filterable] struct {
	cols settlementLineColumns
}

// HasMember filters parents that have a matching Member using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Members).
func (w settlementLineWhereR[Q]) HasMember(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Members.NameExpr()),
		sm.Where(Members.Columns.ID.EQ(w.cols.MemberID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasSettlementRun filters parents that have a matching SettlementRun using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to SettlementRuns).
func (w settlementLineWhereR[Q]) HasSettlementRun(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(SettlementRuns.NameExpr()),
		sm.Where(SettlementRuns.Columns.ID.EQ(w.cols.SettlementRunID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *SettlementLine) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Member":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("settlementLine cannot load %T as %q", retrieved, name)
		}

		o.R.Member = rel
		o.R.Loaded.Member = true

		if rel != nil {
			rel.R.SettlementLines = SettlementLineSlice{o}
		}
		return nil
	case "SettlementRun":
		rel, ok := retrieved.(*SettlementRun)
		if !ok {
			return fmt.Errorf("settlementLine cannot load %T as %q", retrieved, name)
		}

		o.R.SettlementRun = rel
		o.R.Loaded.SettlementRun = true

		if rel != nil {
			rel.R.SettlementLines = SettlementLineSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("settlementLine has no relationship %q", name)
	}
}

type settlementLinePreloader struct {
	Member        func(...psql.PreloadOption) psql.Preloader
	SettlementRun func(...psql.PreloadOption) psql.Preloader
}

func buildSettlementLinePreloader() settlementLinePreloader {
	return settlementLinePreloader{
		Member: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Member, MemberSlice](psql.PreloadRel{
				Name: "Member",
				Sides: []psql.PreloadSide{
					{
						From:        SettlementLines,
						To:          Members,
						FromColumns: []string{"member_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Members.Columns.Names(), memberScanMapperNullable, opts...)
		},
		SettlementRun: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*SettlementRun, SettlementRunSlice](psql.PreloadRel{
				Name: "SettlementRun",
				Sides: []psql.PreloadSide{
					{
						From:        SettlementLines,
						To:          SettlementRuns,
						FromColumns: []string{"settlement_run_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, SettlementRuns.Columns.Names(), settlementRunScanMapperNullable, opts...)
		},
	}
}

