// LoadMember loads the settlementLine's Member into the .R struct
func (o *SettlementLine) LoadMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Member = nil
	o.R.Loaded.Member = false

	related, err := o.Member(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.SettlementLines = SettlementLineSlice{o}

	o.R.Member = related
	o.R.Loaded.Member = true
	return nil
}

// LoadMember loads the settlementLine's Member into the .R struct
func (os SettlementLineSlice) LoadMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.Member(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Member = nil
		o.R.Loaded.Member = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	settlementLineByKey := make(map[uuid.UUID][]*SettlementLine, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		settlementLineByKey[o.MemberID] = append(settlementLineByKey[o.MemberID], o)
	}

	for _, rel := range members {

		owners, ok := settlementLineByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Member != nil {
				continue
			}

			rel.R.SettlementLines = append(rel.R.SettlementLines, o)

			o.R.Member = rel

		}
	}

	return nil
}

