type settlementLineJoins[Q dialect.Joinable] struct {
	typ           string
	Member        modAs[Q, memberColumns]
	SettlementRun modAs[Q, settlementRunColumns]
}

func (j settlementLineJoins[Q]) aliasedAs(alias string) settlementLineJoins[Q] {
	return buildSettlementLineJoins[Q](buildSettlementLineColumns(alias), j.typ)
}

func buildSettlementLineJoins[Q dialect.Joinable](cols settlementLineColumns, typ string) settlementLineJoins[Q] {
	return settlementLineJoins[Q]{
		typ: typ,
		Member: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MemberID),
					))
				}

				return mods
			},
		},
		SettlementRun: modAs[Q, settlementRunColumns]{
			c: SettlementRuns.Columns,
			f: func(to settlementRunColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SettlementRuns.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.SettlementRunID),
					))
				}

				return mods
			},
		},
	}
}
